class Solution {
  private static final int BITS = 20;
  private int[] zero, one, count;
  private int nodes = 1;

  public int maximumStrongPairXor(int[] nums) {
    Arrays.sort(nums);
    int size = nums.length * (BITS + 1) + 2;
    zero = new int[size];
    one = new int[size];
    count = new int[size];
    int left = 0, best = 0;
    for (int right = 0; right < nums.length; right++) {
      update(nums[right], 1);
      while (nums[right] > 2 * nums[left]) update(nums[left++], -1);
      best = Math.max(best, maxXor(nums[right]));
    }
    return best;
  }

  private void update(int value, int delta) {
    int node = 0;
    for (int bit = BITS; bit >= 0; bit--) {
      boolean set = ((value >> bit) & 1) == 1;
      int next = set ? one[node] : zero[node];
      if (next == 0) {
        next = nodes++;
        if (set) one[node] = next;
        else zero[node] = next;
      }
      node = next;
      count[node] += delta;
    }
  }

  private int maxXor(int value) {
    int node = 0, result = 0;
    for (int bit = BITS; bit >= 0; bit--) {
      boolean set = ((value >> bit) & 1) == 1;
      int want = set ? zero[node] : one[node]; // the opposite bit gives a 1 in the xor
      if (want != 0 && count[want] > 0) {
        result |= 1 << bit;
        node = want;
      } else {
        node = set ? one[node] : zero[node];
      }
    }
    return result;
  }
}
